package pe.animetv;
import android.app.Dialog;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.time.Duration;import java.util.concurrent.atomic.AtomicInteger;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.Config;import static org.junit.Assert.*;import static pe.animetv.Models.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,qualifiers="w960dp-h540dp-land-xhdpi")
public class ContinueWatchingTest {
 private ActivityController<TvScreenTest.FakeActivity> controller;private MainActivity activity;private Store store;
 @Before public void start(){controller=Robolectric.buildActivity(TvScreenTest.FakeActivity.class).setup().visible().windowFocusChanged(true);activity=controller.get();store=new Store(activity);store.clearContinueWatching();}
 @After public void stop(){controller.pause().stop().destroy();}
 private Anime item(String slug){return new Anime(slug,"https://animeav1.com/media/"+slug,"","Serie");}
 private void call(String name,Class<?>[] types,Object...args)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(activity,args);}
 private LinearLayout choices(Dialog d){LinearLayout panel=(LinearLayout)((android.view.ViewGroup)d.getWindow().getDecorView().findViewById(android.R.id.content)).getChildAt(0);return (LinearLayout)((ScrollView)panel.getChildAt(1)).getChildAt(0);}
 private FrameLayout card(AtomicInteger clicks,AtomicInteger menus){FrameLayout root=new FrameLayout(activity),card=new FrameLayout(activity);TvUi.focus(card);card.setFocusableInTouchMode(true);card.setOnClickListener(v->clicks.incrementAndGet());LongOk.bind(card,held->menus.incrementAndGet());root.addView(card,new FrameLayout.LayoutParams(300,180));activity.setContentView(root);root.measure(View.MeasureSpec.makeMeasureSpec(960,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(540,View.MeasureSpec.EXACTLY));root.layout(0,0,960,540);assertTrue(card.requestFocus());return card;}
 private KeyEvent key(int action,int repeat){return new KeyEvent(0,SystemClock.uptimeMillis(),action,KeyEvent.KEYCODE_DPAD_CENTER,repeat);}
 @Test public void removingOneKeepsOtherSourcesAndProgress()throws Exception{Anime a=item("one"),b=new Anime("Two","https://tioanime.com/anime/two","", "Serie");store.rememberAnime(a);store.rememberAnime(b);store.lastEpisode(a.url(),a.url()+"/2");store.progress(a.url()+"/2",9000,50000);store.favorite(a,"Por defecto",true);store.removeContinueWatching(a.url());Store restored=new Store(activity);assertEquals(1,restored.history().length());assertEquals(b.url(),restored.history().getJSONObject(0).getString("url"));assertEquals(9000,restored.position(a.url()+"/2"));assertEquals(a.url()+"/2",restored.lastEpisode(a.url()));assertTrue(restored.isFavorite(a.url()));store.rememberAnime(a);assertEquals(2,store.history().length());}
 @Test public void clearingAllKeepsSavedResumePosition(){Anime a=item("one");store.rememberAnime(a);store.lastEpisode(a.url(),"episode");store.progress("episode",12000,60000);store.clearContinueWatching();assertEquals(0,new Store(activity).history().length());assertEquals(12000,store.position("episode"));assertEquals("episode",store.lastEpisode(a.url()));}
 @Test public void shortOkStillClicksOnce(){AtomicInteger clicks=new AtomicInteger(),menus=new AtomicInteger();View v=card(clicks,menus);v.dispatchKeyEvent(key(KeyEvent.ACTION_DOWN,0));Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(80));v.dispatchKeyEvent(key(KeyEvent.ACTION_UP,0));Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofSeconds(1));assertEquals(1,clicks.get());assertEquals(0,menus.get());}
 @Test public void heldOkOpensOnlyOneMenuAndReleaseNeverClicks(){AtomicInteger clicks=new AtomicInteger(),menus=new AtomicInteger();View v=card(clicks,menus);v.dispatchKeyEvent(key(KeyEvent.ACTION_DOWN,0));Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(ViewConfiguration.getLongPressTimeout()+30));v.dispatchKeyEvent(key(KeyEvent.ACTION_DOWN,4));v.dispatchKeyEvent(key(KeyEvent.ACTION_UP,0));assertEquals(1,menus.get());assertEquals(0,clicks.get());}
 @Test public void losingFocusCancelsPendingHold(){AtomicInteger clicks=new AtomicInteger(),menus=new AtomicInteger();View v=card(clicks,menus);v.dispatchKeyEvent(key(KeyEvent.ACTION_DOWN,0));v.clearFocus();Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofSeconds(1));v.dispatchKeyEvent(key(KeyEvent.ACTION_UP,0));assertEquals(0,menus.get());assertEquals(0,clicks.get());}
 @Test public void menuRequiresExplicitRemovalAndCancelPreservesHistory()throws Exception{Anime a=item("one");store.rememberAnime(a);call("removeContinueMenu",new Class<?>[]{Anime.class,int.class,boolean.class},a,0,false);Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertEquals(1,store.history().length());choices(d).findViewWithTag("continue-cancel").performClick();assertEquals(1,store.history().length());assertFalse(d.isShowing());call("removeContinueMenu",new Class<?>[]{Anime.class,int.class,boolean.class},a,0,false);d=org.robolectric.shadows.ShadowDialog.getLatestDialog();choices(d).findViewWithTag("continue-remove").performClick();assertEquals(0,store.history().length());assertFalse(d.isShowing());}
 @Test public void settingsClearConfirmationUpdatesValueAndPreservesProgress()throws Exception{Anime a=item("one");store.rememberAnime(a);store.progress("episode",8000,60000);LinearLayout field=TvUi.setting(activity,"Limpiar Seguir viendo","Eliminar todos",()->{});call("clearContinueMenu",new Class<?>[]{LinearLayout.class},field);Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();choices(d).findViewWithTag("continue-cancel").performClick();assertEquals(1,store.history().length());call("clearContinueMenu",new Class<?>[]{LinearLayout.class},field);d=org.robolectric.shadows.ShadowDialog.getLatestDialog();choices(d).findViewWithTag("continue-clear-confirm").performClick();assertEquals(0,store.history().length());assertEquals("Sin episodios",((TextView)field.getChildAt(1)).getText());assertEquals(8000,store.position("episode"));}
 @Test public void realContinueCardsExposeLongPressMenu()throws Exception{Anime a=item("one");store.rememberAnime(a);LinearLayout body=new LinearLayout(activity);call("continueWatching",new Class<?>[]{LinearLayout.class,org.json.JSONArray.class},body,store.history());TvRowsView.Rail rail=(TvRowsView.Rail)body.getChildAt(0);View card=rail.model.items.get(0);assertTrue(card.isLongClickable());assertTrue(card.performLongClick());Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertNotNull(choices(d).findViewWithTag("continue-remove"));d.dismiss();}
 @Test public void originalHeldReleaseCannotConfirmRemoval()throws Exception{Anime a=item("one");store.rememberAnime(a);call("removeContinueMenu",new Class<?>[]{Anime.class,int.class,boolean.class},a,0,true);Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();choices(d).findViewWithTag("continue-remove").requestFocus();assertTrue(d.dispatchKeyEvent(key(KeyEvent.ACTION_DOWN,3)));assertTrue(d.dispatchKeyEvent(key(KeyEvent.ACTION_UP,0)));assertEquals(1,store.history().length());assertTrue(d.isShowing());choices(d).findViewWithTag("continue-remove").performClick();assertEquals(0,store.history().length());}
 @Test public void cleanOptionIsInPlaybackSettings()throws Exception{call("settings",new Class<?>[]{});Field field=MainActivity.class.getDeclaredField("catalogView");field.setAccessible(true);TvRowsView rows=(TvRowsView)field.get(activity);LinearLayout dashboard=(LinearLayout)rows.model.items.get(1);TvRowsView options=(TvRowsView)dashboard.getChildAt(1);View clean=options.model.items.stream().filter(v->"continue-clear-setting".equals(v.getTag())).findFirst().orElseThrow();assertTrue(clean.isFocusable());clean.performClick();Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertNotNull(choices(d).findViewWithTag("continue-clear-confirm"));d.dismiss();}
}
